import React, { forwardRef } from 'react';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import Text from '@dynatrace/strato-design-tokens/typography';

import { getSymbol } from './functions/get-symbol.js';
import { Flex } from '../../../../../../layouts-core/flex/Flex.js';
import { markerGroupKey } from '../../functions/marker-group-key.js';
import { useAnnotationsSelectionState } from '../../hooks/store/selectors.js';
import { useSetStateSelection } from '../../hooks/store/state-setters.js';
import { useMarkersInteractions } from '../../hooks/useMarkersInteractions.js';
import { AnnotationData } from '../../types/annotations.js';

const StyledTooltipItemContent = /* @__PURE__ */ styled(Flex)({
  alignItems: 'center',
  padding: `${Spacings.Size4} ${Spacings.Size0}`,
  width: '100%',
  '&:hover': {
    backgroundColor: Colors.Background.Base.Default,
    cursor: 'pointer',
  },
});

const StyledSymbol = /* @__PURE__ */ styled('div')({
  padding: `0 ${Spacings.Size4}`,
  width: '18px',
  textAlign: 'center',
});

const StyledSymbolContainer = /* @__PURE__ */ styled('div')({
  padding: '0',
  flex: '0 0 30px',
});

const StyledTextContainer = /* @__PURE__ */ styled('div')<{
  emphasized: boolean;
}>(({ emphasized }) => ({
  fontWeight: `${
    emphasized
      ? Text.Text.Base.Emphasized.Weight
      : Text.Text.Base.Default.Weight
  }`,
}));

type AnnotationsTooltipItemProps = {
  annotation: AnnotationData;
  onMouseOver: (event: React.MouseEvent) => void;
};

export const AnnotationsTooltipItem = forwardRef<
  HTMLDivElement,
  AnnotationsTooltipItemProps
>(({ annotation, onMouseOver }, forwardedRef) => {
  const { description, end, start, symbol, title, id } = annotation;
  const { hoveredItem } = useAnnotationsSelectionState();
  const updateSelectionState = useSetStateSelection();
  const { onMarkersInteraction } = useMarkersInteractions();

  const groupKey = markerGroupKey(start, end);
  const isEmphasized = groupKey === hoveredItem;

  const handleMouseOver = (event: React.MouseEvent) => {
    const newSelection = {
      hoveredListItem: id,
      hoverGroupListKey: groupKey,
    };
    updateSelectionState(newSelection);
    onMarkersInteraction?.(newSelection);

    onMouseOver(event);
  };

  const symbolContent = getSymbol(symbol);

  return (
    <StyledTooltipItemContent
      onMouseOver={handleMouseOver}
      ref={forwardedRef}
      data-testid={'annotations-tooltip-item'}
    >
      <StyledSymbolContainer>
        <StyledSymbol>{symbolContent}</StyledSymbol>
      </StyledSymbolContainer>
      <StyledTextContainer emphasized={isEmphasized}>
        <div>{title}</div>
        <div>{description}</div>
      </StyledTextContainer>
    </StyledTooltipItemContent>
  );
});

AnnotationsTooltipItem['displayName'] = 'AnnotationsTooltipItem';
